(function () {
    cc.SicBoPlayer = cc.Class({
        "extends": cc.Component,
        properties: {
            lbName: cc.Label,
			lbChip: cc.Label,
			lbWin: cc.Label,
			nodeAvaShield : cc.Node,
            nickName: ""
        },

        onLoad: function () {
            // Defensive: prefab co the chua wire het cc.Node fields - khong duoc
            // de onLoad throw vi se kill ca SicBoView component graph (50+ slots),
            // dan toi UI hong: chip khong bay, state change khong xu ly.
            try { this.animation = this.node.getComponent(cc.Animation); } catch (e) {}
            try {
                this.nodeChat = this.node.getChildByName('chat');
                this.nodeEmotion = this.nodeChat && this.nodeChat.getChildByName('emotion');
                this.nodeBubble = this.nodeChat && this.nodeChat.getChildByName('bubble');
                this.skeEmotion = this.nodeEmotion && this.nodeEmotion.getComponent(sp.Skeleton);
                this.lbBubbleChat = this.nodeBubble && this.nodeBubble.getComponentInChildren(cc.Label);
                if (this.nodeChat) this.nodeChat.active = false;
            } catch (e) {}
            try { this.avatar = this.node.getComponentInChildren(cc.Avatar); } catch (e) {}
            try { this.nodeWin = this.node.getChildByName('win'); } catch (e) {}
            try { this.animLbWin = this.lbWin && this.lbWin.node && this.lbWin.node.parent && this.lbWin.node.parent.getComponent(cc.Animation); } catch (e) {}
            try { this.nodeInfo = this.node.getChildByName('ava_money'); } catch (e) {}
            if (this.nodeAvaShield) this.nodeAvaShield.active = false;
            if (this.nodeInfo) this.nodeInfo.active = false;
        },
		
        showEmotion: function (index, message) {
            if (!this.skeEmotion || !this.animation) return;
            if (this.nodeBubble) this.nodeBubble.active = false;
            if (this.nodeEmotion) this.nodeEmotion.active = true;

            this.skeEmotion.clearTracks();
            this.skeEmotion.setToSetupPose();

            //fix loi server cam chat sexy
            if (index === 15) {
                this.skeEmotion.setAnimation(index, '16-extreme-sexy-girl', true);
            } else {
                this.skeEmotion.setAnimation(index, message[1], true);
            }

            this.animation.play('showBubbleChat');
        },

        showBubbleChat: function (message) {
            if (this.nodeBubble) this.nodeBubble.active = true;
            if (this.nodeEmotion) this.nodeEmotion.active = false;
            if (this.lbBubbleChat) this.lbBubbleChat.string = message[1];
            if (this.animation) this.animation.play('showBubbleChat');
        },
        //reset lai UI ket qua
        resetPlayerResultUI: function () {
            if (this.nodeWin) this.nodeWin.active = false;
        },
        //set ket qua cho player
        playerResultUI: function (amount, balance) {
            if (this.nodeWin) this.nodeWin.active = true;
            if (this.lbWin) this.lbWin.string = '+' + cc.Tool.getInstance().formatNumberK(amount);
            if (this.animLbWin) this.animLbWin.play('winEffect');
            if (balance) {
                this.updateChip(balance);
            }

        },

        updateChip: function (chip) {
            if (this.lbChip) this.lbChip.string = '$ ' + cc.Tool.getInstance().formatNumberK(chip);
        },

        updateChipNormal: function (chip) {
            if (this.lbChip) this.lbChip.string =  '$ ' + cc.Tool.getInstance().formatNumberK(chip);
        },
		
        onDestroy: function () {
            this.unRegisterPlayer();
        },
        //player vao phong
        registerPlayer: function (accountInfo) {
            if (!accountInfo) return;
            // Defensive: server bot/user co the bcast Nickname (chuan PascalCase) hoac
            // NickName (typo client cu). Fallback ca 2 + default neu null.
            var nick = accountInfo.Nickname || accountInfo.NickName || ('user_' + (accountInfo.AccountID || ''));
            var avatarID = accountInfo.Avatar;
            if (typeof avatarID !== 'number' || avatarID <= 0) {
                avatarID = 1;
            }
            if (this.avatar) this.avatar.setAvatar(cc.AccountController.getInstance().getAvatarImage(avatarID));
            if (this.nodeInfo) this.nodeInfo.active = true;
            if (this.nodeAvaShield) this.nodeAvaShield.active = true;
            this.nickName = nick;
            var maxLen = accountInfo.ServiceID ? 7 : 10;
            if (this.lbName) this.lbName.string = cc.Config.getInstance().formatName(nick, maxLen);
            if (this.lbChip) this.lbChip.string = '$ ' + cc.Tool.getInstance().formatNumberK(accountInfo.Balance || 0);
        },

        //player roi phong
        unRegisterPlayer: function () {
            try { if (this.avatar) this.avatar.setAvatar(cc.LobbyController.getInstance().getGameAssets().avatarDef); } catch (e) {}
            if (this.nodeInfo) this.nodeInfo.active = false;
            if (this.nodeAvaShield) this.nodeAvaShield.active = false;
            try {
                if (this.nodeBubble) this.nodeBubble.active = false;
                if (this.nodeEmotion) this.nodeEmotion.active = false;
            } catch (e) {

            }
        },

        updateConnectionStatus: function (status) {
            switch (status) {
                case cc.ConnectionStatus.DISCONNECTED:
                    break;
                case cc.ConnectionStatus.CONNECTED:
                    break;
            }
        },

        updatePlayerStatus: function (playerStatus) {
            this.playerStatus = playerStatus.toString();
            if (playerStatus.toString() === cc.PlayerStatus.INGAME) {
                this.node.opacity = 255;
            } else {
                this.node.opacity = 150;
            }
        },


    });
}).call(this);